# New specifier types for enhanced functionality

class Auto(object):
    """Placeholder specifier that represents automatic handling.
    For the purposes of this release, it simply returns the target unchanged.
    """
    def __init__(self):
        pass
    def glomit(self, target, scope):
        return target
    def __repr__(self):
        return 'Auto()'

class Fill(object):
    """Specifies that a missing value should be filled with a default.
    The default value is stored and returned when the spec is evaluated.
    """
    def __init__(self, default):
        self.default = default
    def glomit(self, target, scope):
        return self.default
    def __repr__(self):
        return f'Fill({self.default!r})'

class Let(object):
    """Simple variable binding specifier.
    ``Let(name, value, body)`` binds ``name`` to ``value`` in the scope
    before evaluating ``body``.
    """
    def __init__(self, name, value, body):
        self.name = name
        self.value = value
        self.body = body
    def glomit(self, target, scope):
        # create a new scope with the variable bound
        new_scope = scope.copy()
        new_scope[self.name] = self.value
        return self.body.glomit(target, new_scope)
    def __repr__(self):
        return f'Let({self.name!r}, {self.value!r}, {self.body!r})'

# ROOT is a specifier that returns the target itself
ROOT = Path()

class Invoke(object):
    """Invoke a callable with optional constants.
    ``Invoke(func, *constants, **kwargs)`` will call ``func`` with the
    constants and the target as the first argument.
    """
    def __init__(self, func, *constants, **kwargs):
        self.func = func
        self.constants = constants
        self.kwargs = kwargs
    def glomit(self, target, scope):
        return self.func(target, *self.constants, **self.kwargs)
    def __repr__(self):
        consts = ', '.join(repr(c) for c in self.constants)
        kw = ', '.join(f'{k}={v!r}' for k, v in self.kwargs.items())
        all_args = ', '.join(filter(None, [consts, kw]))
        return f'Invoke({self.func.__name__}, {all_args})'
